// RegisterCodeOrchestrationTools registers the agent-facing tools that cover
// the whole API surface. Called from RegisterTools in place of the per-endpoint
// registrations when MCP.Orchestration is "code".
func RegisterCodeOrchestrationTools(s *server.MCPServer) {
	s.AddTool(
		mcplib.NewTool("sendfox_search",
			mcplib.WithDescription("Search the sendfox API for endpoints matching a natural-language query. Returns a ranked list of {endpoint_id, method, path, summary} entries. Call this first to find the endpoint to execute."),
			mcplib.WithString("query", mcplib.Required(), mcplib.Description("Natural-language description of what you want to do.")),
			mcplib.WithNumber("limit", mcplib.Description("Max endpoints to return (default 10, max 100).")),
			mcplib.WithReadOnlyHintAnnotation(true),
			mcplib.WithDestructiveHintAnnotation(false),
			mcplib.WithOpenWorldHintAnnotation(false),
		),
		handleCodeOrchSearch,
	)

	s.AddTool(
		mcplib.NewTool("sendfox_get",
			mcplib.WithDescription("Get schemas and metadata for one endpoint by its endpoint_id (from sendfox_search). This registry-only lookup never calls the API."),
			mcplib.WithString("endpoint_id", mcplib.Required(), mcplib.Description("Endpoint identifier returned by sendfox_search (e.g., \"contacts.list\").")),
			mcplib.WithReadOnlyHintAnnotation(true),
			mcplib.WithDestructiveHintAnnotation(false),
			mcplib.WithOpenWorldHintAnnotation(false),
		),
		handleCodeOrchGet,
	)

	s.AddTool(
		mcplib.NewTool("sendfox_execute",
			mcplib.WithDescription("Execute one sendfox API endpoint by its endpoint_id (from sendfox_search). Discover schemas with sendfox_get first. Mutations default to dry_run=true; execution requires confirm=true. Sends, scheduling, activation, forms/domains and destructive actions also require approve_sensitive=true. No automatic write retries."),
			mcplib.WithString("endpoint_id", mcplib.Required(), mcplib.Description("Endpoint identifier returned by sendfox_search (e.g., \"contacts.list\").")),
			mcplib.WithObject("params", mcplib.Description("Parameters for the endpoint. Path placeholders match by name; remaining entries become query string on GET/DELETE or JSON body on POST/PUT/PATCH.")),
			mcplib.WithBoolean("dry_run", mcplib.Description("Preview without sending; defaults true for mutations.")),
			mcplib.WithBoolean("confirm", mcplib.Description("Explicit approval to execute a mutation after reviewing its preview.")),
			mcplib.WithBoolean("approve_sensitive", mcplib.Description("Additional explicit human approval for sends, scheduling, activation, forms/domains and destructive actions.")),
		),
		handleCodeOrchExecute,
	)
}

